-- ============================================================
-- INDEXES (excluding those backing a PK/UNIQUE constraint)
-- ============================================================
CREATE INDEX idx_advantages_campaign_created ON public.advantages USING btree (campaign_id, created_at DESC);

CREATE INDEX idx_advantages_character_pending ON public.advantages USING btree (character_id, created_at DESC) WHERE (consumed_at IS NULL);

CREATE INDEX idx_bug_reports_created ON public.bug_reports USING btree (created_at DESC);

CREATE INDEX idx_bug_reports_status ON public.bug_reports USING btree (status, created_at DESC);

CREATE INDEX campaign_events_pending_idx ON public.campaign_events USING btree (campaign_id, scheduled_canon_day, scheduled_canon_hour) WHERE ((applied_canon_day IS NULL) AND (cancelled_at IS NULL));

CREATE INDEX idx_ci_campaign ON public.campaign_invitations USING btree (campaign_id);

CREATE INDEX idx_ci_recipient ON public.campaign_invitations USING btree (recipient_user_id, status);

CREATE INDEX idx_ci_sender ON public.campaign_invitations USING btree (sender_user_id, created_at DESC);

CREATE INDEX campaign_members_campaign_id_idx ON public.campaign_members USING btree (campaign_id);

CREATE INDEX campaign_members_campaign_user_idx ON public.campaign_members USING btree (campaign_id, user_id);

CREATE INDEX campaign_members_user_id_idx ON public.campaign_members USING btree (user_id);

CREATE INDEX idx_campaign_notes_edited_clone ON public.campaign_notes USING btree (source_module_version_id, edited_since_clone) WHERE (source_module_version_id IS NOT NULL);

CREATE INDEX idx_campaign_notes_sort_order ON public.campaign_notes USING btree (campaign_id, sort_order);

CREATE INDEX idx_campaign_notes_source_module_version ON public.campaign_notes USING btree (source_module_version_id) WHERE (source_module_version_id IS NOT NULL);

