CREATE POLICY advantages_delete ON public.advantages AS PERMISSIVE FOR DELETE TO public USING ((EXISTS ( SELECT 1
   FROM campaigns c
  WHERE ((c.id = advantages.campaign_id) AND (c.gm_user_id = auth.uid())))));

CREATE POLICY advantages_insert ON public.advantages AS PERMISSIVE FOR INSERT TO public WITH CHECK ((EXISTS ( SELECT 1
   FROM campaigns c
  WHERE ((c.id = advantages.campaign_id) AND (c.gm_user_id = auth.uid())))));

CREATE POLICY advantages_select ON public.advantages AS PERMISSIVE FOR SELECT TO public USING ((((consumed_at IS NOT NULL) AND (EXISTS ( SELECT 1
   FROM campaign_members cm
  WHERE ((cm.campaign_id = advantages.campaign_id) AND (cm.user_id = auth.uid()))))) OR (EXISTS ( SELECT 1
   FROM characters c
  WHERE ((c.id = advantages.character_id) AND (c.user_id = auth.uid())))) OR (EXISTS ( SELECT 1
   FROM campaigns c
  WHERE ((c.id = advantages.campaign_id) AND (c.gm_user_id = auth.uid()))))));

CREATE POLICY advantages_thriver_bypass ON public.advantages AS PERMISSIVE FOR ALL TO public USING (is_thriver()) WITH CHECK (is_thriver());

