   FROM characters c
  WHERE ((c.id = advantages.character_id) AND (c.user_id = auth.uid())))) OR (EXISTS ( SELECT 1
   FROM campaigns c
  WHERE ((c.id = advantages.campaign_id) AND (c.gm_user_id = auth.uid())))))) WITH CHECK (((EXISTS ( SELECT 1
