CREATE OR REPLACE FUNCTION public.bump_module_latest_version()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  UPDATE public.modules
    SET latest_version_id = NEW.id
  WHERE id = NEW.module_id
    AND (latest_version_id IS NULL
         OR (SELECT published_at FROM public.module_versions WHERE id = latest_version_id) < NEW.published_at);
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.bump_npc_relationship_cmod(p_npc_id uuid, p_character_id uuid, p_delta integer, p_clamp_min integer DEFAULT '-3'::integer, p_clamp_max integer DEFAULT 3, p_set_revealed boolean DEFAULT false, p_reveal_level text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_authorized boolean;
BEGIN
  -- Caller must be one of:
  --   (a) the character's owner (player rolling their own First
  --       Impression / Barter), or
  --   (b) the GM of the NPC's campaign, or
  --   (c) a thriver (godmode).
  SELECT
    EXISTS (
      SELECT 1 FROM public.characters ch
      WHERE ch.id = p_character_id AND ch.user_id = auth.uid()
    )
    OR EXISTS (
      SELECT 1 FROM public.campaign_npcs n
      JOIN public.campaigns c ON c.id = n.campaign_id
      WHERE n.id = p_npc_id AND c.gm_user_id = auth.uid()
    )
    OR public.is_thriver()
  INTO v_authorized;

  IF NOT COALESCE(v_authorized, false) THEN
    RAISE EXCEPTION 'Unauthorized: caller % cannot bump relationship for character %', auth.uid(), p_character_id
      USING ERRCODE = '42501';
  END IF;

  INSERT INTO public.npc_relationships AS r
    (npc_id, character_id, relationship_cmod, revealed, reveal_level)
  VALUES (
    p_npc_id,
    p_character_id,
    GREATEST(p_clamp_min, LEAST(p_clamp_max, p_delta)),
    p_set_revealed,
    CASE WHEN p_set_revealed THEN p_reveal_level ELSE NULL END
  )
  ON CONFLICT (npc_id, character_id) DO UPDATE SET
    relationship_cmod =
      GREATEST(p_clamp_min, LEAST(p_clamp_max, r.relationship_cmod + p_delta)),
    revealed     = r.revealed OR p_set_revealed,
    reveal_level = COALESCE(r.reveal_level,
                            CASE WHEN p_set_revealed THEN p_reveal_level ELSE NULL END),
    updated_at   = now();
END;
$function$
;

CREATE OR REPLACE FUNCTION public.bump_world_community_subscriber_count()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
BEGIN
  IF TG_OP = 'INSERT' THEN
    UPDATE public.world_communities
      SET subscriber_count = subscriber_count + 1
      WHERE id = NEW.world_community_id;
    RETURN NEW;
  ELSIF TG_OP = 'DELETE' THEN
    UPDATE public.world_communities
      SET subscriber_count = GREATEST(0, subscriber_count - 1)
      WHERE id = OLD.world_community_id;
    RETURN OLD;
  END IF;
  RETURN NULL;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.call_notify_thriver(p_type text, p_title text, p_body text, p_link text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
BEGIN
  PERFORM net.http_post(
    url := current_setting('app.settings.supabase_url', true) || '/functions/v1/notify-thriver',
    headers := jsonb_build_object(
      'Content-Type', 'application/json',
      'Authorization', 'Bearer ' || current_setting('app.settings.service_role_key', true)
    ),
    body := jsonb_build_object(
      'type', p_type,
      'title', p_title,
      'body', p_body,
      'link', p_link
    )
  );
EXCEPTION WHEN OTHERS THEN
  -- Silently swallow pg_net / Edge Function failures so the parent
  -- transaction (the signup that triggered us) doesn't roll back.
  NULL;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.campfire_touch_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN NEW.updated_at := now(); RETURN NEW; END;
$function$
;

CREATE OR REPLACE FUNCTION public.check_rate_limit(p_action text, p_max_per_hour integer)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_user uuid := auth.uid();
  v_bucket timestamptz := date_trunc('hour', now());
  v_new_count int;
BEGIN
  -- Anonymous callers (no auth.uid()) can't be rate-limited per-user;
  -- treat them as unrestricted for plumbing simplicity. The signup
  -- flow + bug-report-from-ghost paths rely on this.
  IF v_user IS NULL THEN RETURN true; END IF;
  INSERT INTO rate_limits (user_id, action, hour_bucket, count)
    VALUES (v_user, p_action, v_bucket, 1)
    ON CONFLICT (user_id, action, hour_bucket)
    DO UPDATE SET count = rate_limits.count + 1
    RETURNING count INTO v_new_count;
  RETURN v_new_count <= p_max_per_hour;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.enforce_moderation_on_insert()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_is_thriver boolean;
BEGIN
  SELECT lower(role) = 'thriver' INTO v_is_thriver
    FROM public.profiles WHERE id = auth.uid();

  IF COALESCE(v_is_thriver, false) THEN
    -- Thriver inserts: respect status, but force approved_by to the
    -- real auth.uid() so a thriver cannot credit a different thriver.
    IF NEW.moderation_status = 'approved' THEN
      NEW.approved_by := auth.uid();
      NEW.approved_at := COALESCE(NEW.approved_at, now());
    END IF;
    RETURN NEW;
  END IF;

  -- Non-thriver inserts: scope decides moderation outcome.
  IF NEW.campaign_id IS NOT NULL THEN
    NEW.moderation_status := 'approved';
    NEW.approved_by := NULL;  -- system-approved by campaign-scope rule
    NEW.approved_at := now();
  ELSE
    NEW.moderation_status := 'pending';
    NEW.approved_by := NULL;
    NEW.approved_at := NULL;
  END IF;

  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.forum_replies_after_delete()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  newest timestamptz;
BEGIN
  SELECT MAX(created_at) INTO newest
    FROM public.forum_replies
   WHERE thread_id = OLD.thread_id;

  UPDATE public.forum_threads
     SET reply_count = GREATEST(reply_count - 1, 0),
         latest_reply_at = COALESCE(newest, created_at)
   WHERE id = OLD.thread_id;
  RETURN OLD;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.forum_replies_after_insert()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  UPDATE public.forum_threads
     SET reply_count = reply_count + 1,
         latest_reply_at = NEW.created_at
   WHERE id = NEW.thread_id;
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.forum_touch_updated_at()
 RETURNS trigger
