$function$
;

CREATE OR REPLACE FUNCTION public.get_latest_messages_for_conversations(conv_ids uuid[])
 RETURNS TABLE(conversation_id uuid, body text, created_at timestamp with time zone, sender_user_id uuid)
 LANGUAGE sql
 STABLE
AS $function$
  SELECT DISTINCT ON (m.conversation_id)
    m.conversation_id, m.body, m.created_at, m.sender_user_id
  FROM   public.messages m
  WHERE  m.conversation_id = ANY(conv_ids)
  ORDER  BY m.conversation_id, m.created_at DESC;
$function$
;

CREATE OR REPLACE FUNCTION public.get_or_create_dm(other_user_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  conv_id uuid;
BEGIN
  -- Find an existing 1:1 conversation between the two users (exactly 2 participants).
  SELECT cp1.conversation_id INTO conv_id
  FROM   conversation_participants cp1
  JOIN   conversation_participants cp2
         ON  cp2.conversation_id = cp1.conversation_id
         AND cp2.user_id = other_user_id
  WHERE  cp1.user_id = auth.uid()
    AND  (SELECT COUNT(*) FROM conversation_participants cp3
          WHERE cp3.conversation_id = cp1.conversation_id) = 2
  LIMIT 1;

  IF conv_id IS NULL THEN
    INSERT INTO conversations DEFAULT VALUES RETURNING id INTO conv_id;
    INSERT INTO conversation_participants (conversation_id, user_id)
    VALUES (conv_id, auth.uid()), (conv_id, other_user_id);
  END IF;

  RETURN conv_id;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_visitor_map_data()
 RETURNS TABLE(ip_hash text, lat numeric, lng numeric, city text, country_code text, visit_count bigint, first_visit timestamp with time zone, last_visit timestamp with time zone, is_ghost boolean)
 LANGUAGE sql
 SECURITY DEFINER
AS $function$
    SELECT vl.ip_hash, MAX(vl.latitude) as lat, MAX(vl.longitude) as lng,
      MAX(vl.city) as city, MAX(vl.country_code) as country_code,
      COUNT(*) as visit_count, MIN(vl.created_at) as first_visit,
      MAX(vl.created_at) as last_visit, BOOL_AND(vl.is_ghost) as is_ghost
    FROM visitor_logs vl
    WHERE vl.ip_hash IS NOT NULL AND vl.latitude IS NOT NULL AND vl.longitude IS NOT NULL
    GROUP BY vl.ip_hash ORDER BY visit_count DESC
  $function$
;

CREATE OR REPLACE FUNCTION public.handle_campaign_invitation_response()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_recipient_name text;
  v_campaign_name text;
BEGIN
  IF NEW.status = OLD.status THEN RETURN NEW; END IF;
  IF NEW.status NOT IN ('accepted','declined') THEN RETURN NEW; END IF;
  SELECT username INTO v_recipient_name FROM public.profiles WHERE id = NEW.recipient_user_id;
  SELECT name INTO v_campaign_name FROM public.campaigns WHERE id = NEW.campaign_id;
  IF NEW.status = 'accepted' THEN
    BEGIN
      INSERT INTO public.campaign_members (campaign_id, user_id) VALUES (NEW.campaign_id, NEW.recipient_user_id);
    EXCEPTION WHEN unique_violation THEN
      -- Already a member; silently accept.
      NULL;
    END;
  END IF;
  -- Notify the sender of the response.
  INSERT INTO public.notifications (user_id, type, title, body, link, metadata)
  VALUES (
    NEW.sender_user_id,
    'campaign_invitation_response',
    CASE WHEN NEW.status = 'accepted' THEN 'Invitation accepted' ELSE 'Invitation declined' END,
    COALESCE(v_recipient_name, 'Someone') || ' ' || NEW.status || ' your invitation to "' || COALESCE(v_campaign_name, 'a campaign') || '"',
    CASE WHEN NEW.status = 'accepted' THEN '/stories/' || NEW.campaign_id::text ELSE NULL END,
    jsonb_build_object(
      'invitation_id', NEW.id,
      'campaign_id', NEW.campaign_id,
      'recipient_name', COALESCE(v_recipient_name, 'Someone'),
      'status', NEW.status
    )
  );
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.handle_new_user()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
BEGIN
  BEGIN
    INSERT INTO public.profiles (id, username, email, role)
    VALUES (
      NEW.id,
      COALESCE(NEW.raw_user_meta_data->>'username', split_part(NEW.email, '@', 1)),
      NEW.email,
      'Survivor'
    )
    ON CONFLICT (id) DO UPDATE SET email = EXCLUDED.email;
  EXCEPTION WHEN OTHERS THEN
    -- Log the failure but do not abort the auth user creation.
    RAISE WARNING 'handle_new_user failed for %: %', NEW.id, SQLERRM;
  END;
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.increment_portrait_counter(g text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  new_count integer;
BEGIN
  IF g NOT IN ('man', 'woman') THEN
    RAISE EXCEPTION 'invalid gender: %', g;
  END IF;
  UPDATE public.portrait_counters
    SET count = count + 1
    WHERE gender = g
    RETURNING count INTO new_count;
  RETURN new_count;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.is_thriver()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
AS $function$
  -- profiles.role is auto-lowercased by trg_normalize_role (see
  -- tasks/lessons.md), so compare against 'thriver' (lowercase).
  -- The original 'Thriver' check silently no-op'd every godmode
  -- policy - fixed by sql/thriver-role-case-fix.sql.
  SELECT EXISTS (
    SELECT 1 FROM public.profiles
    WHERE id = auth.uid() AND role = 'thriver'
  );
$function$
;

CREATE OR REPLACE FUNCTION public.is_user_suspended()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT EXISTS (
    SELECT 1 FROM profiles
    WHERE id = auth.uid()
      AND suspended_until IS NOT NULL
      AND suspended_until > now()
  );
$function$
;

