 SET search_path TO 'public'
AS $function$
  SELECT conversation_id
  FROM   conversation_participants
  WHERE  user_id = auth.uid()
$function$
;

CREATE OR REPLACE FUNCTION public.normalize_profile_role()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  NEW.role := LOWER(NEW.role);
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.notify_bug_report()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  v_who text;
BEGIN
  v_who := COALESCE(NEW.reporter_name, NEW.reporter_email, 'an unknown user');
  PERFORM public.call_notify_thriver(
    'bug_report',
    '🐛 New bug report from ' || v_who,
    'Page: ' || COALESCE(NEW.page_url, '(unknown)') || E'\n\n' ||
    'Description:' || E'\n' || NEW.description || E'\n\n' ||
    'User-Agent: ' || COALESCE(NEW.user_agent, '(unknown)'),
    NEW.page_url
  );
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.notify_campaign_invitation()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_sender_name text;
  v_campaign_name text;
BEGIN
  IF NEW.status <> 'pending' THEN RETURN NEW; END IF;
  SELECT username INTO v_sender_name FROM public.profiles WHERE id = NEW.sender_user_id;
  SELECT name INTO v_campaign_name FROM public.campaigns WHERE id = NEW.campaign_id;
  INSERT INTO public.notifications (user_id, type, title, body, link, metadata)
  VALUES (
    NEW.recipient_user_id,
    'campaign_invitation',
    'Campaign invitation',
    COALESCE(v_sender_name, 'Someone') || ' invited you to "' || COALESCE(v_campaign_name, 'a campaign') || '"',
    NULL, -- click-through handled by inline Accept button, not a navigation
    jsonb_build_object(
      'invitation_id', NEW.id,
      'campaign_id', NEW.campaign_id,
      'campaign_name', COALESCE(v_campaign_name, 'a campaign'),
      'sender_name', COALESCE(v_sender_name, 'Someone'),
      'message', NEW.message
    )
  );
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.notify_character_changed()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_username text;
  v_campaign_name text;
  v_char_name text;
BEGIN
  IF OLD.character_id IS NOT DISTINCT FROM NEW.character_id THEN RETURN NEW; END IF;
  IF NEW.character_id IS NULL THEN RETURN NEW; END IF;

  SELECT username INTO v_username FROM profiles WHERE id = NEW.user_id;
  SELECT name INTO v_campaign_name FROM campaigns WHERE id = NEW.campaign_id;
  SELECT name INTO v_char_name FROM characters WHERE id = NEW.character_id;

  -- First character assignment = "joined as", subsequent = "is now playing as"
  IF OLD.character_id IS NULL THEN
    INSERT INTO notifications (user_id, type, title, body, link)
    SELECT cm.user_id, 'player_joined', 'New Player',
      COALESCE(v_username, 'Someone') || ' joined ' || COALESCE(v_campaign_name, 'a campaign') || ' as ' || COALESCE(v_char_name, 'a character'),
      '/campaigns/' || NEW.campaign_id
    FROM campaign_members cm
    WHERE cm.campaign_id = NEW.campaign_id
      AND cm.user_id != NEW.user_id;
  ELSE
    INSERT INTO notifications (user_id, type, title, body, link)
    SELECT cm.user_id, 'player_joined', 'Character Change',
      COALESCE(v_username, 'Someone') || ' is now playing as ' || COALESCE(v_char_name, 'a new character') || ' in ' || COALESCE(v_campaign_name, 'a campaign'),
      '/campaigns/' || NEW.campaign_id
    FROM campaign_members cm
    WHERE cm.campaign_id = NEW.campaign_id
      AND cm.user_id != NEW.user_id;
  END IF;

  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.notify_community_encounter()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_recipient_user_id uuid;
  v_recipient_source_community_id uuid;
  v_recipient_community_name text;
  v_encountering_username text;
  v_encountering_campaign_name text;
BEGIN
  SELECT c.gm_user_id, wc.name, wc.source_community_id
    INTO v_recipient_user_id, v_recipient_community_name, v_recipient_source_community_id
  FROM public.world_communities wc
  JOIN public.campaigns c ON c.id = wc.source_campaign_id
  WHERE wc.id = NEW.world_community_id;

  SELECT username INTO v_encountering_username
    FROM public.profiles WHERE id = NEW.encountering_user_id;
  SELECT name INTO v_encountering_campaign_name
    FROM public.campaigns WHERE id = NEW.encountering_campaign_id;

  IF v_recipient_user_id IS NULL OR v_recipient_user_id = NEW.encountering_user_id THEN
    RETURN NEW;
  END IF;

  INSERT INTO public.notifications (user_id, type, title, body, link, metadata)
  VALUES (
    v_recipient_user_id,
    'community_encounter',
    'Cross-Campaign Encounter',
    COALESCE(v_encountering_username, 'Another GM') || '''s campaign "'
      || COALESCE(v_encountering_campaign_name, 'unknown') || '" encountered your community "'
      || COALESCE(v_recipient_community_name, 'unknown') || '"'
      || CASE WHEN NEW.narrative IS NOT NULL AND length(NEW.narrative) > 0
              THEN ': ' || NEW.narrative ELSE '' END,
    '/communities/' || v_recipient_source_community_id::text,
    jsonb_build_object(
      'encounter_id', NEW.id,
      'world_community_id', NEW.world_community_id,
      'encountering_campaign_id', NEW.encountering_campaign_id,
      'encountering_campaign_name', v_encountering_campaign_name,
      'encountering_username', v_encountering_username,
      'recipient_community_name', v_recipient_community_name,
      'narrative', NEW.narrative
    )
  );
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.notify_community_link()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_recipient_user_id uuid;
  v_recipient_community_id uuid;
  v_recipient_community_name text;
  v_proposer_community_name text;
  v_proposer_username text;
BEGIN
  v_recipient_community_id := CASE
    WHEN NEW.proposed_from_community_id = NEW.community_a_id THEN NEW.community_b_id
    ELSE NEW.community_a_id
  END;

  SELECT wc.name, c.gm_user_id, wc.source_community_id
    INTO v_recipient_community_name, v_recipient_user_id, v_recipient_community_id
  FROM public.world_communities wc
  JOIN public.campaigns c ON c.id = wc.source_campaign_id
  WHERE wc.id = (CASE
    WHEN NEW.proposed_from_community_id = NEW.community_a_id THEN NEW.community_b_id
    ELSE NEW.community_a_id
  END);

  SELECT wc.name INTO v_proposer_community_name
    FROM public.world_communities wc
    WHERE wc.id = NEW.proposed_from_community_id;

  SELECT username INTO v_proposer_username
    FROM public.profiles WHERE id = NEW.proposed_by_user_id;

  IF v_recipient_user_id IS NULL THEN
    RETURN NEW;
  END IF;

  INSERT INTO public.notifications (user_id, type, title, body, link, metadata)
  VALUES (
    v_recipient_user_id,
    'community_link_proposal',
    CASE NEW.link_type
      WHEN 'trade' THEN '💱 Trade route proposed'
      WHEN 'alliance' THEN '🤝 Alliance proposed'
      WHEN 'feud' THEN '⚔️ Feud declared'
      ELSE 'Community link proposed'
    END,
    COALESCE(v_proposer_username, 'Another GM') || ' proposes a '
      || NEW.link_type || ' between "'
      || COALESCE(v_proposer_community_name, 'unknown') || '" and your "'
      || COALESCE(v_recipient_community_name, 'unknown') || '"'
      || CASE WHEN NEW.narrative IS NOT NULL AND length(NEW.narrative) > 0
              THEN ': ' || NEW.narrative ELSE '' END,
    '/communities/' || v_recipient_community_id::text,
    jsonb_build_object(
      'link_id', NEW.id,
      'link_type', NEW.link_type,
      'community_a_id', NEW.community_a_id,
      'community_b_id', NEW.community_b_id,
      'proposed_from_community_id', NEW.proposed_from_community_id,
      'proposer_community_name', v_proposer_community_name,
      'recipient_community_name', v_recipient_community_name,
      'proposer_username', v_proposer_username,
      'narrative', NEW.narrative
    )
  );
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.notify_community_link_response()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_proposer_user_id uuid;
  v_proposer_community_id uuid;
  v_proposer_community_name text;
  v_recipient_community_name text;
  v_other_id uuid;
BEGIN
  IF OLD.status = 'pending' AND NEW.status IN ('active', 'declined') THEN
    v_proposer_user_id := NEW.proposed_by_user_id;
    SELECT wc.name, wc.source_community_id INTO v_proposer_community_name, v_proposer_community_id
      FROM public.world_communities wc WHERE wc.id = NEW.proposed_from_community_id;
    v_other_id := CASE
      WHEN NEW.proposed_from_community_id = NEW.community_a_id THEN NEW.community_b_id
      ELSE NEW.community_a_id
    END;
    SELECT wc.name INTO v_recipient_community_name
      FROM public.world_communities wc WHERE wc.id = v_other_id;

    IF v_proposer_user_id IS NOT NULL THEN
      INSERT INTO public.notifications (user_id, type, title, body, link, metadata)
      VALUES (
        v_proposer_user_id,
        'community_link_response',
        CASE
          WHEN NEW.status = 'active' THEN '✓ Link accepted'
          ELSE '✗ Link declined'
        END,
        '"' || COALESCE(v_recipient_community_name, 'unknown')
          || '" ' || NEW.status || ' your ' || NEW.link_type
          || ' proposal with "' || COALESCE(v_proposer_community_name, 'unknown') || '"',
        '/communities/' || v_proposer_community_id::text,
        jsonb_build_object(
          'link_id', NEW.id,
          'link_type', NEW.link_type,
          'status', NEW.status,
          'proposer_community_name', v_proposer_community_name,
          'recipient_community_name', v_recipient_community_name
        )
      );
    END IF;
  END IF;
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.notify_community_migration()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_target_user_id uuid;
  v_target_community_id uuid;
  v_target_community_name text;
  v_offerer_username text;
BEGIN
  SELECT wc.source_community_id, wc.name, c.gm_user_id
    INTO v_target_community_id, v_target_community_name, v_target_user_id
  FROM public.world_communities wc
  JOIN public.campaigns c ON c.id = wc.source_campaign_id
  WHERE wc.id = NEW.target_world_community_id;

  SELECT username INTO v_offerer_username
    FROM public.profiles WHERE id = NEW.offered_by_user_id;

  IF v_target_user_id IS NULL THEN
    RETURN NEW;
  END IF;

  INSERT INTO public.notifications (user_id, type, title, body, link, metadata)
  VALUES (
    v_target_user_id,
    'community_migration',
    '📤 Migration request',
    'Survivor "' || NEW.npc_name || '" from "' || NEW.source_community_name
      || '" seeks shelter in your "' || COALESCE(v_target_community_name, 'unknown') || '"'
      || CASE WHEN NEW.narrative IS NOT NULL AND length(NEW.narrative) > 0
              THEN ': ' || NEW.narrative ELSE '' END,
    '/communities/' || v_target_community_id::text,
    jsonb_build_object(
      'migration_id', NEW.id,
      'npc_name', NEW.npc_name,
      'source_community_name', NEW.source_community_name,
      'target_community_name', v_target_community_name,
      'offerer_username', v_offerer_username,
      'narrative', NEW.narrative
    )
  );
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.notify_community_migration_response()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_target_community_name text;
BEGIN
  IF OLD.status = 'pending' AND NEW.status IN ('accepted', 'declined') THEN
    SELECT wc.name INTO v_target_community_name
      FROM public.world_communities wc
      WHERE wc.id = NEW.target_world_community_id;
    IF NEW.offered_by_user_id IS NOT NULL THEN
      INSERT INTO public.notifications (user_id, type, title, body, link, metadata)
      VALUES (
        NEW.offered_by_user_id,
        'community_migration_response',
        CASE WHEN NEW.status = 'accepted' THEN '✓ Migrant accepted' ELSE '✗ Migrant declined' END,
        '"' || COALESCE(v_target_community_name, 'unknown') || '" '
          || NEW.status || ' "' || NEW.npc_name || '" from your "'
          || NEW.source_community_name || '"',
        '/communities/' || NEW.source_community_id::text,
        jsonb_build_object(
          'migration_id', NEW.id,
          'npc_name', NEW.npc_name,
          'status', NEW.status,
          'target_community_name', v_target_community_name
        )
      );
    END IF;
  END IF;
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.notify_community_milestone()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_community_id uuid;
  v_count int;
  v_already_notified boolean;
  v_leader_user_id uuid;
  v_community_name text;
  v_has_status boolean;
BEGIN
  -- Which community are we evaluating? For DELETEs this would be OLD,
  -- but we don't trigger on DELETE (a community shrinking back below
  -- 13 stays a community in-fiction; no un-notify).
  v_community_id := NEW.community_id;

  -- Pull the community row + flag. Bail early if already notified
  -- so we don't do the expensive count.
  SELECT leader_user_id, name, notified_community_milestone
    INTO v_leader_user_id, v_community_name, v_already_notified
  FROM public.communities
  WHERE id = v_community_id;

  IF v_already_notified IS TRUE THEN
    RETURN NEW;
  END IF;

  -- Detect whether community_members.status exists (migration may or
  -- may not have landed); count active members accordingly.
  SELECT EXISTS (
    SELECT 1 FROM information_schema.columns
    WHERE table_schema = 'public'
      AND table_name = 'community_members'
      AND column_name = 'status'
  ) INTO v_has_status;

  IF v_has_status THEN
    SELECT count(*) INTO v_count
    FROM public.community_members
    WHERE community_id = v_community_id
      AND left_at IS NULL
      AND COALESCE(status, 'active') = 'active';
  ELSE
    SELECT count(*) INTO v_count
    FROM public.community_members
    WHERE community_id = v_community_id
      AND left_at IS NULL;
  END IF;

  IF v_count >= 13 AND v_leader_user_id IS NOT NULL THEN
    INSERT INTO public.notifications (user_id, type, title, body, link)
    VALUES (
      v_leader_user_id,
      'community_milestone',
      'Your group is now a Community',
      COALESCE(v_community_name, 'Your group') || ' has grown to ' || v_count || ' members - it''s officially a Community now.',
      '/communities'
    );

    UPDATE public.communities
    SET notified_community_milestone = true
    WHERE id = v_community_id;
  END IF;

  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.notify_inventory_received(target_character_id uuid, item_name text, item_qty integer, from_label text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id uuid;
  v_target_char_name text;
BEGIN
  -- Resolve owner of the receiving character.
  SELECT user_id, name
    INTO v_user_id, v_target_char_name
    FROM public.characters
    WHERE id = target_character_id;

  -- No owner (orphaned / NPC character row), nothing to notify.
  IF v_user_id IS NULL THEN
    RETURN;
  END IF;

  -- Don't notify yourself if you somehow give to your own character.
  IF v_user_id = auth.uid() THEN
    RETURN;
  END IF;

  INSERT INTO public.notifications (user_id, type, title, body, metadata)
  VALUES (
    v_user_id,
    'inventory_received',
    'Item received',
    'You received ' || item_qty::text || '× ' || item_name
      || ' from ' || COALESCE(from_label, 'someone'),
    jsonb_build_object(
      'item_name', item_name,
      'qty', item_qty,
      'from_label', from_label,
      'target_character_id', target_character_id,
      'target_character_name', v_target_char_name
    )
  );
END;
$function$
;

CREATE OR REPLACE FUNCTION public.notify_lfg_interest()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_author uuid;
  v_username text;
  v_title text;
BEGIN
  SELECT author_user_id, title INTO v_author, v_title
    FROM public.lfg_posts
   WHERE id = NEW.post_id;

  -- Defensive: should never trigger because the INSERT policy blocks self-
  -- interest, but skip just in case (notifying yourself is noise).
  IF v_author IS NULL OR v_author = NEW.interested_user_id THEN
    RETURN NEW;
  END IF;

  SELECT username INTO v_username
    FROM public.profiles
   WHERE id = NEW.interested_user_id;

  INSERT INTO public.notifications (user_id, type, title, body, link)
  VALUES (
    v_author,
    'lfg_interest',
    'New interest on your LFG post',
    COALESCE(v_username, 'Someone') || ' is interested in "' || COALESCE(v_title, 'your post') || '"',
    '/campfire/lfg#lfg-' || NEW.post_id::text
  );
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.notify_module_version_published()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_module_name text;
  v_module_author_id uuid;
BEGIN
  SELECT name, author_user_id
    INTO v_module_name, v_module_author_id
  FROM public.modules WHERE id = NEW.module_id;

  -- One notification per subscribing campaign's GM. Skip
  -- subscriptions that are already on this version (shouldn't
  -- happen on INSERT, but defensive) and skip the author's own
  -- campaigns (they obviously know what they just published).
  INSERT INTO public.notifications (user_id, type, title, body, link, metadata)
  SELECT
    c.gm_user_id,
    'module_version_published',
    '📦 Module updated',
    'A new version of "' || COALESCE(v_module_name, 'Unknown module')
      || '" (v' || NEW.version || ') is available'
      || CASE WHEN NEW.changelog IS NOT NULL AND length(NEW.changelog) > 0
              THEN ': ' || NEW.changelog ELSE '' END,
    '/stories/' || c.id::text || '/modules/' || NEW.module_id::text || '/versions',
    jsonb_build_object(
      'module_id', NEW.module_id,
      'module_name', v_module_name,
      'version_id', NEW.id,
      'version', NEW.version,
      'version_major', NEW.version_major,
      'version_minor', NEW.version_minor,
      'version_patch', NEW.version_patch,
      'changelog', NEW.changelog,
      'subscribing_campaign_id', c.id,
      'subscribing_campaign_name', c.name
    )
  FROM public.module_subscriptions ms
  JOIN public.campaigns c ON c.id = ms.campaign_id
  WHERE ms.module_id = NEW.module_id
    AND ms.status = 'active'
    AND ms.current_version_id IS DISTINCT FROM NEW.id
    AND c.gm_user_id IS DISTINCT FROM v_module_author_id;

  RETURN NEW;
END;
$function$
;

