CREATE OR REPLACE FUNCTION public.notify_world_community_moderation()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_recipient_user_id uuid;
  v_source_community_id uuid;
BEGIN
  IF NEW.moderation_status = OLD.moderation_status THEN
    RETURN NEW;
  END IF;
  v_recipient_user_id := NEW.published_by;
  v_source_community_id := NEW.source_community_id;
  IF v_recipient_user_id IS NULL THEN
    RETURN NEW;
  END IF;

  INSERT INTO public.notifications (user_id, type, title, body, link, metadata)
  VALUES (
    v_recipient_user_id,
    'world_community_moderation',
    CASE NEW.moderation_status
      WHEN 'approved' THEN '✓ Community approved'
      WHEN 'rejected' THEN '✗ Community rejected'
      ELSE 'Community moderation updated'
    END,
    CASE NEW.moderation_status
      WHEN 'approved' THEN
        'Your published community "' || NEW.name
        || '" is now live on the world map. Other GMs can see it, propose links, and route their PCs into an encounter with it.'
      WHEN 'rejected' THEN
        'Your published community "' || NEW.name
        || '" was rejected by a Thriver. The source campaign community is untouched; you can edit the public metadata and re-submit for moderation via Community ▾.'
      ELSE
        'Your published community "' || NEW.name
        || '" moderation state is now: ' || NEW.moderation_status
    END,
    '/communities/' || v_source_community_id::text,
    jsonb_build_object(
      'world_community_id', NEW.id,
      'source_community_id', v_source_community_id,
      'name', NEW.name,
      'moderation_status', NEW.moderation_status,
      'previous_moderation_status', OLD.moderation_status
    )
  );
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.notify_world_community_public_update()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_editor_username text;
  v_field_changes text[] := ARRAY[]::text[];
BEGIN
  -- Don't fire on moderation transitions - the moderation notifier
  -- handles those. A moderation flip also usually lands at the same
  -- instant as approved_by/approved_at; suppress those too.
  IF NEW.moderation_status IS DISTINCT FROM OLD.moderation_status THEN
    RETURN NEW;
  END IF;

  -- Collect which fields changed so the notification body can
  -- summarize. Only count the public-facing ones.
  IF NEW.name IS DISTINCT FROM OLD.name THEN
    v_field_changes := array_append(v_field_changes, 'name');
  END IF;
  IF NEW.description IS DISTINCT FROM OLD.description THEN
    v_field_changes := array_append(v_field_changes, 'description');
  END IF;
  IF NEW.faction_label IS DISTINCT FROM OLD.faction_label THEN
    v_field_changes := array_append(v_field_changes, 'faction');
  END IF;
  IF NEW.size_band IS DISTINCT FROM OLD.size_band THEN
    v_field_changes := array_append(v_field_changes, 'size');
  END IF;
  IF NEW.community_status IS DISTINCT FROM OLD.community_status THEN
    v_field_changes := array_append(v_field_changes, 'status');
  END IF;
  IF NEW.homestead_lat IS DISTINCT FROM OLD.homestead_lat
     OR NEW.homestead_lng IS DISTINCT FROM OLD.homestead_lng THEN
    v_field_changes := array_append(v_field_changes, 'homestead');
  END IF;

  -- No visible change? Skip. (Covers bookkeeping-only UPDATEs like
  -- last_public_update_at without other changes, or pure
  -- approved_by / approved_at touches.)
  IF cardinality(v_field_changes) = 0 THEN
    RETURN NEW;
  END IF;

  SELECT username INTO v_editor_username
    FROM public.profiles WHERE id = NEW.published_by;

  INSERT INTO public.notifications (user_id, type, title, body, link, metadata)
  SELECT p.id,
    'world_community_updated',
    '✎ Community updated',
    COALESCE(v_editor_username, 'Someone') || ' updated public info on "'
      || NEW.name || '" ('
      || array_to_string(v_field_changes, ', ') || ').',
    '/map',
    jsonb_build_object(
      'world_community_id', NEW.id,
      'source_community_id', NEW.source_community_id,
      'fields_changed', v_field_changes
    )
  FROM public.profiles p
  WHERE p.role = 'thriver'
    AND p.id IS DISTINCT FROM NEW.published_by;

  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.notify_world_community_subscribers_update()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_editor_username text;
  v_field_changes text[] := ARRAY[]::text[];
BEGIN
  -- Skip moderation flips (handled elsewhere) and any pure-bookkeeping
  -- UPDATE.
  IF NEW.moderation_status IS DISTINCT FROM OLD.moderation_status THEN
    RETURN NEW;
  END IF;

  IF NEW.name IS DISTINCT FROM OLD.name THEN
    v_field_changes := array_append(v_field_changes, 'name');
  END IF;
  IF NEW.description IS DISTINCT FROM OLD.description THEN
    v_field_changes := array_append(v_field_changes, 'description');
  END IF;
  IF NEW.faction_label IS DISTINCT FROM OLD.faction_label THEN
    v_field_changes := array_append(v_field_changes, 'faction');
  END IF;
  IF NEW.size_band IS DISTINCT FROM OLD.size_band THEN
    v_field_changes := array_append(v_field_changes, 'size');
  END IF;
  IF NEW.community_status IS DISTINCT FROM OLD.community_status THEN
    v_field_changes := array_append(v_field_changes, 'status');
  END IF;
  IF NEW.homestead_lat IS DISTINCT FROM OLD.homestead_lat
     OR NEW.homestead_lng IS DISTINCT FROM OLD.homestead_lng THEN
    v_field_changes := array_append(v_field_changes, 'homestead');
  END IF;

  IF cardinality(v_field_changes) = 0 THEN
    RETURN NEW;
  END IF;

  SELECT username INTO v_editor_username
    FROM public.profiles WHERE id = NEW.published_by;

  INSERT INTO public.notifications (user_id, type, title, body, link, metadata)
  SELECT s.user_id,
    'world_community_followed_updated',
    '★ ' || NEW.name || ' updated',
    COALESCE(v_editor_username, 'A leader') || ' updated public info on "'
      || NEW.name || '" ('
      || array_to_string(v_field_changes, ', ') || ').',
    '/communities',
    jsonb_build_object(
      'world_community_id', NEW.id,
      'name', NEW.name,
      'changed_fields', v_field_changes,
      'editor_username', v_editor_username,
      'community_status', NEW.community_status
    )
  FROM public.community_subscriptions s
  WHERE s.world_community_id = NEW.id
    -- Don't notify the editor themselves about their own change.
    AND s.user_id IS DISTINCT FROM NEW.published_by;
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.trg_maintain_mortal_recovery_flag()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF NEW.wp_current = 0 THEN
    NEW.recovering_from_mortal_wound := true;
  ELSIF NEW.wp_current >= NEW.wp_max THEN
    NEW.recovering_from_mortal_wound := false;
  END IF;
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.player_notes_set_session_number()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF NEW.session_number IS NULL THEN
    SELECT CASE WHEN c.session_status = 'active' THEN c.session_count ELSE NULL END
    INTO NEW.session_number
    FROM public.campaigns c
    WHERE c.id = NEW.campaign_id;
  END IF;
  RETURN NEW;
END;
$function$
;

