CREATE OR REPLACE FUNCTION public.rate_limits_purge_old()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  DELETE FROM rate_limits WHERE hour_bucket < now() - interval '1 day';
END;
$function$
;

CREATE OR REPLACE FUNCTION public.redeem_signup_code(p_code text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_row signup_codes%ROWTYPE;
BEGIN
  IF p_code IS NULL OR length(trim(p_code)) = 0 THEN
    RETURN false;
  END IF;
  -- Lock the row so concurrent redeems don't both succeed past max_uses.
  SELECT * INTO v_row FROM signup_codes WHERE code = trim(p_code) FOR UPDATE;
  IF NOT FOUND THEN RETURN false; END IF;
  IF v_row.expires_at IS NOT NULL AND v_row.expires_at < now() THEN RETURN false; END IF;
  IF v_row.used_count >= v_row.max_uses THEN RETURN false; END IF;
  UPDATE signup_codes SET used_count = used_count + 1 WHERE code = v_row.code;
  RETURN true;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.refresh_module_subscriber_count()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  affected_ids uuid[];
BEGIN
  -- Collect every module_id the firing row(s) reference. UPDATE may
  -- have moved the subscription to a different module (rare but
  -- possible) so we union OLD + NEW.
  IF TG_OP = 'INSERT' THEN
    affected_ids := ARRAY[NEW.module_id];
  ELSIF TG_OP = 'DELETE' THEN
    affected_ids := ARRAY[OLD.module_id];
  ELSE
    -- UPDATE: handle module_id move + status changes.
    affected_ids := ARRAY[OLD.module_id, NEW.module_id];
  END IF;

  UPDATE public.modules m
    SET subscriber_count = (
      SELECT COUNT(*)::int
      FROM public.module_subscriptions s
      WHERE s.module_id = m.id
        AND s.status = 'active'
    )
    WHERE m.id = ANY(affected_ids);

  RETURN NULL;  -- AFTER trigger, return value ignored
END;
$function$
;

CREATE OR REPLACE FUNCTION public.reveal_npc_on_initiative_insert()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF NEW.npc_id IS NOT NULL THEN
    UPDATE public.campaign_npcs
       SET hidden_from_players = false
     WHERE id = NEW.npc_id
       AND hidden_from_players = true;
  END IF;
  RETURN NEW;
END $function$
;

CREATE OR REPLACE FUNCTION public.reveal_npc_on_scene_token_insert()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF NEW.npc_id IS NOT NULL THEN
    UPDATE public.campaign_npcs
       SET hidden_from_players = false
     WHERE id = NEW.npc_id
       AND hidden_from_players = true;
  END IF;
  RETURN NEW;
END $function$
;

CREATE OR REPLACE FUNCTION public.snap_token_to_seat(p_scene_id uuid, p_assignee_id uuid, p_kind text, p_target_x integer, p_target_y integer)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_campaign_id uuid;
  v_authorized boolean;
BEGIN
  -- Resolve scene to its campaign so we can authorize against members.
  SELECT campaign_id INTO v_campaign_id
  FROM tactical_scenes
  WHERE id = p_scene_id;

  IF v_campaign_id IS NULL THEN
    RAISE EXCEPTION 'snap_token_to_seat: scene % not found', p_scene_id;
  END IF;

  -- Authorize: GM of the campaign OR any campaign_members row for the
  -- calling user. Anyone with seat-popout access should qualify here.
  SELECT
    EXISTS (
      SELECT 1 FROM campaigns
      WHERE id = v_campaign_id AND gm_user_id = auth.uid()
    )
    OR
    EXISTS (
      SELECT 1 FROM campaign_members
      WHERE campaign_id = v_campaign_id AND user_id = auth.uid()
    )
  INTO v_authorized;

  IF NOT v_authorized THEN
    RAISE EXCEPTION 'snap_token_to_seat: caller % is not a member of campaign %', auth.uid(), v_campaign_id;
  END IF;

  -- Perform the targeted UPDATE. Bypasses scene_tokens RLS via the
  -- SECURITY DEFINER context. We restrict the UPDATE to scene+assignee,
  -- so the worst a caller can do via this RPC is reposition a PC/NPC
  -- token onto the (x, y) they computed. They cannot edit other columns,
  -- delete tokens, or touch tokens outside the named scene.
  IF p_kind = 'pc' THEN
    UPDATE scene_tokens
    SET grid_x = p_target_x, grid_y = p_target_y
    WHERE scene_id = p_scene_id AND character_id = p_assignee_id;
  ELSIF p_kind = 'npc' THEN
    UPDATE scene_tokens
    SET grid_x = p_target_x, grid_y = p_target_y
    WHERE scene_id = p_scene_id AND npc_id = p_assignee_id;
  ELSE
    RAISE EXCEPTION 'snap_token_to_seat: invalid kind %', p_kind;
  END IF;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.update_vehicle_in_campaign(p_campaign_id uuid, p_vehicle_id text, p_new_vehicle jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_authorized boolean;
  v_existing jsonb;
  v_elem jsonb;
  v_next jsonb;
  v_found boolean := false;
BEGIN
  -- Authorize: GM of the campaign OR any campaign_members row for
  -- the calling user. Matches the popout's own canEdit gate.
  SELECT
    EXISTS (
      SELECT 1 FROM campaigns
      WHERE id = p_campaign_id AND gm_user_id = auth.uid()
    )
    OR
    EXISTS (
      SELECT 1 FROM campaign_members
      WHERE campaign_id = p_campaign_id AND user_id = auth.uid()
    )
  INTO v_authorized;

  IF NOT v_authorized THEN
    RAISE EXCEPTION 'update_vehicle_in_campaign: caller % is not a member of campaign %', auth.uid(), p_campaign_id;
  END IF;

  -- Sanity: the supplied vehicle blob must carry its own id and it
  -- must match p_vehicle_id, so a caller can't smuggle in a write
  -- targeted at a different vehicle. String comparison - vehicle.id
  -- is an arbitrary slug, not a uuid.
  IF (p_new_vehicle->>'id') IS NULL OR (p_new_vehicle->>'id') <> p_vehicle_id THEN
    RAISE EXCEPTION 'update_vehicle_in_campaign: p_new_vehicle.id must equal p_vehicle_id';
  END IF;

  -- Pull current vehicles array, map over it replacing the matching
  -- entry. Builds a new array element-by-element rather than using
  -- jsonb_set with a discovered index, so the implementation stays
  -- readable and a missing entry naturally falls through to the
  -- append branch.
  SELECT vehicles INTO v_existing FROM campaigns WHERE id = p_campaign_id;
  IF v_existing IS NULL THEN
    v_existing := '[]'::jsonb;
  END IF;

  v_next := '[]'::jsonb;
  FOR v_elem IN
    SELECT value FROM jsonb_array_elements(v_existing) AS t(value)
  LOOP
    IF (v_elem->>'id') = p_vehicle_id THEN
      v_next := v_next || jsonb_build_array(p_new_vehicle);
      v_found := true;
    ELSE
      v_next := v_next || jsonb_build_array(v_elem);
    END IF;
  END LOOP;

  IF NOT v_found THEN
    v_next := v_next || jsonb_build_array(p_new_vehicle);
  END IF;

  UPDATE campaigns SET vehicles = v_next WHERE id = p_campaign_id;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.war_stories_touch_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  NEW.updated_at := now();
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.war_story_replies_after_delete()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE newest timestamptz;
BEGIN
  SELECT MAX(created_at) INTO newest FROM public.war_story_replies WHERE war_story_id = OLD.war_story_id;
  UPDATE public.war_stories
     SET reply_count = GREATEST(reply_count - 1, 0),
         latest_reply_at = newest
   WHERE id = OLD.war_story_id;
  RETURN OLD;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.war_story_replies_after_insert()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  UPDATE public.war_stories
     SET reply_count = reply_count + 1, latest_reply_at = NEW.created_at
   WHERE id = NEW.war_story_id;
  RETURN NEW;
END;
$function$
;
